void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord / iResolution.xy;

    float value = texelFetch(iChannel0, ivec2(fragCoord / CELL_SIZE), 0).r;
    vec3 col = vec3(0);
    col += vec3(1.0, 0.0, 0.0) * smoothstep(0.55, 0.45, abs(value - 0.0));
    col += vec3(0.0, 0.8, 0.0) * smoothstep(0.55, 0.45, abs(value - 1.0));
    col += vec3(0.0, 0.0, 1.0) * smoothstep(0.55, 0.45, abs(value - 2.0));
    col += vec3(1.0, 0.5, 0.0) * smoothstep(0.55, 0.45, abs(value - 3.0));
    col += vec3(0.0, 1.0, 1.0) * smoothstep(0.55, 0.45, abs(value - 4.0));
    col += vec3(1.0, 0.0, 1.0) * smoothstep(0.55, 0.45, abs(value - 5.0));
    col += vec3(1.0, 1.0, 1.0) * smoothstep(0.55, 0.45, abs(value - 6.0));

    // lower saturation a bit
    col = mix(vec3(0.7), col, 0.6);

    // make cells circular
    #ifdef CIRCULAR_CELLS
        vec2 g = fract(fragCoord * 1.0 / CELL_SIZE) - 0.5;
        col.rgb *= smoothstep(0.6, 0.3, length(g));
    #endif

    // Output to screen
    fragColor = vec4(col,1.0);
}

