////////////////////////////////////
//
// Common
//
////////////////////////////////////


// size of the cells
#define CELL_SIZE 1.0


// how many neighbors a cell has to lose to in order to be taken over
#define BEATEN_BY 2

// number of elements
// 1 = One color, nothing happens
// 2 = One dominates the other, converges rapidly to mono-colored
// 3 = Rock, Paper, Scissors
// 4 = Rock, Paper, Scissors, Well
// 5 = Rock, Paper, Scissors, Spock, Lizard
#define NUM_ELEMENTS 5.0


// Pseudo-random value from 2D-Vector
float rnd(vec2 p)
{
    p = fract(sin(p * 123.456) * 321.913);
    p *= dot(p, p + vec2(12.34, 14.43));
    return fract(p.x + p.y);
}

