//
////////////////////////////////////
//
// Buffer A
//
// Setup:
// iChannel0: Buffer A
// iChannel1: random texture
//
////////////////////////////////////

#define ROCK 0
#define PAPER 1
#define SCISSORS 2
#define SPOCK 3
#define LIZARD 4

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    vec2 mouse = iMouse.xy / iResolution.xy;

    float value = 0.0;

    float numElements = 3.;

    if (iMouse.z > 0.0) {
        // initialize
        numElements = 3.;
        value = floor(pow(rnd(uv + iMouse.xy),1.0/sqrt(iMouse.x)) * 3.0);
    } else if (iFrame < 2) {
        // initialize
        value = floor(rnd(uv) * 3.0);
    } else {
        // do simulation step
        int count[5];
        int me = int(texelFetch(iChannel0, ivec2(fragCoord), 0).r);

        for (int y = -1; y <= 1; y++) {
            for (int x = -1; x <= 1; x++) {
                int op = int(texelFetch(iChannel0, ivec2(fragCoord) + ivec2(x, y), 0).r);
                count[op]++;
            }
        }

        int im = me-(me/3)+2*count[(me+2)%int(numElements)];

        if (me%count[(me+2)%int(numElements)] == me){
            me = (me+1)%int(numElements);
        }

        if (me == ROCK && count[PAPER] + count[SPOCK] < im
            || me == SCISSORS && count[ROCK] + count[SPOCK] >= im && count[ROCK] >= count[SPOCK]
            || me == LIZARD && count[ROCK] + count[SCISSORS] >= im && count[ROCK] >= count[SCISSORS])
            value = float(ROCK);
        else if (me == PAPER && count[SCISSORS] + count[LIZARD] < im
            || me == SPOCK && count[PAPER] + count[LIZARD] >= im && count[PAPER] >= count[LIZARD]
            || me == ROCK && count[PAPER] + count[SPOCK] >= im && count[PAPER] >= count[SPOCK])
            value = float(PAPER);
        else if (me == SCISSORS && count[SPOCK] + count[ROCK] < im
            || me == LIZARD && count[SCISSORS] + count[ROCK] >= im && count[SCISSORS] >= count[ROCK]
            || me == PAPER && count[SCISSORS] + count[LIZARD] >= im && count[SCISSORS] >= count[LIZARD])
            value = float(SCISSORS);
        else if (me == SPOCK && count[LIZARD] + count[PAPER] < im
            || me == ROCK && count[SPOCK] + count[PAPER] >= im && count[SPOCK] >= count[PAPER]
            || me == SCISSORS && count[SPOCK] + count[ROCK] >= im && count[SPOCK] >= count[ROCK])
            value = float(SPOCK);
        else if (me == LIZARD && count[ROCK] + count[SCISSORS] < im
            || me == PAPER && count[LIZARD] + count[SCISSORS] >= im && count[LIZARD] >= count[SCISSORS]
            || me == SPOCK && count[LIZARD] + count[PAPER] >= im && count[LIZARD] >= count[PAPER])
            value = float(LIZARD);
        else value = 7.0;
    }

    fragColor = vec4(value);
}
